-- 1. updated_at column + auto-update trigger (to measure how long a script is stuck)
alter table public.media_scripts
  add column if not exists updated_at timestamptz not null default now();

-- backfill existing rows so the watchdog doesn't reset healthy old rows
update public.media_scripts set updated_at = coalesce(generated_at, now()) where updated_at is null;

create or replace function public.set_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists trg_media_scripts_updated_at on public.media_scripts;
create trigger trg_media_scripts_updated_at
  before update on public.media_scripts
  for each row execute function public.set_updated_at();

-- 2. Watchdog function: reset scripts stuck in 'generating_images' (step3 was
--    killed by Vercel's 60s timeout before it could start the render or run its
--    catch block). Resetting to 'none' lets the next step3 cron retry them.
create or replace function omnira_cron.reset_stuck_scripts()
returns integer language plpgsql security definer set search_path = '' as $$
declare n integer;
begin
  update public.media_scripts
     set video_status = 'none'
   where video_status = 'generating_images'
     and status = 'approved'
     and published_at is null
     and updated_at < now() - interval '8 minutes'
     and generated_at > now() - interval '24 hours';
  get diagnostics n = row_count;
  if n > 0 then raise notice 'reset % stuck script(s)', n; end if;
  return n;
end $$;

