-- Atomisk claim: markerar pending → running, sätter lease + attempts++. SKIP LOCKED = ingen dubbelkörning.
create or replace function omnira_cron.claim_runs(p_limit int, p_lease_seconds int default 280)
returns setof public.runs
language plpgsql security definer set search_path to '' as $$
begin
  return query
  update public.runs r set
    status      = 'running',
    claimed_at  = now(),
    started_at  = coalesce(r.started_at, now()),
    lease_until = now() + make_interval(secs => p_lease_seconds),
    attempts    = r.attempts + 1
  where r.id in (
    select id from public.runs
    where status = 'pending' and attempts < max_attempts
    order by created_at
    for update skip locked
    limit p_limit
  )
  returning r.*;
end $$;

-- Reaper: återställ fastnade 'running' (lease utgången) → pending (eller failed vid max attempts).
create or replace function omnira_cron.reap_stuck_runs()
returns int language plpgsql security definer set search_path to '' as $$
declare n int;
begin
  update public.runs set
    status      = case when attempts >= max_attempts then 'failed' else 'pending' end,
    error       = case when attempts >= max_attempts then coalesce(last_error,'Lease expired (stuck run)') else error end,
    finished_at = case when attempts >= max_attempts then now() else finished_at end,
    claimed_at  = null,
    lease_until = null
  where status = 'running' and lease_until is not null and lease_until < now();
  get diagnostics n = row_count;
  return n;
end $$;

