-- PR-2 (Finding A) — idempotent reconciliation.
-- The schema/policy/backfill were already present in prod (applied out-of-band);
-- this records the migration in the ledger as a verified no-op. Same end-state as
-- the committed file supabase/migrations/20260606_pr2_route_webhook_isolation.sql.

-- 1) Leak stop: remove permissive authenticated read policy (no-op if already gone).
drop policy if exists "authenticated_read_comment_replies" on public.comment_replies;

-- 2) Structural scoping: project_id column + index (no-op if present).
alter table public.comment_replies
  add column if not exists project_id uuid references public.projects(id) on delete cascade;
create index if not exists idx_comment_replies_project on public.comment_replies (project_id);

-- 3) Backfill via post_id → media_scripts → project (idempotent; only fills NULLs that match).
update public.comment_replies cr
set    project_id = ms.project_id
from   public.media_scripts ms
where  cr.project_id is null
  and  ms.project_id is not null
  and  (
        (cr.platform = 'instagram' and cr.post_id = ms.instagram_media_id)
     or (cr.platform = 'facebook'  and cr.post_id = ms.facebook_post_id)
      );

-- 4) Owner-scoped read policy — guarded so re-apply is a no-op (no drop of the live policy).
do $$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname='public' and tablename='comment_replies'
      and policyname='comment_replies_owner_read'
  ) then
    create policy "comment_replies_owner_read"
      on public.comment_replies for select
      to authenticated
      using (project_id in (select id from public.projects where owner_id = auth.uid()));
  end if;
end $$;

